#include <print>

int main() {
    int bonus = 5;

    auto add = [bonus](int s) {
        return s + bonus;
    };

    std::println("{}", add(80));
    std::println("{}", add(60));

    bonus = 200;
    std::println("外面的 bonus 换了衣服，用的还是抄下的 5：{}", add(1));

    // 想永远用最新值，得换一种带法：包里存能跟着原件走的东西，后面一课讲

    return 0;
}

